    --bg-color: #0a0a0a;
    --surface-color: #1a1a1a;
    --surface-color-light: #2a2a2a;
    --text-primary: #f5f5f5;
    --text-secondary: #a0a0a0;
    --accent-color: #d4af37; /* Gold */
    --accent-hover: #f1c40f;
    --border-color: #333;

    --font-heading: 'Playfair Display', serif;
    --font-body: 'Inter', sans-serif;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: var(--font-body);
    background-color: var(--bg-color);
    color: var(--text-primary);
    line-height: 1.6;
    overflow-x: hidden;
}

a {
    text-decoration: none;
    color: inherit;
    transition: color 0.3s ease;
}

ul {
    list-style: none;
}

img {
    max-width: 100%;
    display: block;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 2rem;
}

.section-title {
    font-family: var(--font-heading);
    font-size: 2.5rem;
    text-align: center;
    margin-bottom: 3rem;
    font-weight: 600;
}

/* Header */
.navbar {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    background-color: rgba(10, 10, 10, 0.95);
    backdrop-filter: blur(10px);
    z-index: 1000;
    border-bottom: 1px solid var(--border-color);
    padding: 1rem 0;
}

.navbar-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-family: var(--font-heading);
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 2px;
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a {
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 500;
}

.nav-links a:hover {
    color: var(--accent-color);
}

.nav-icons {
    display: flex;
    gap: 1.5rem;
    align-items: center;
}

.nav-icons i {
    font-size: 1.2rem;
    cursor: pointer;
    transition: color 0.3s ease;
}

.nav-icons i:hover {
    color: var(--accent-color);
}

.cart-icon {
    position: relative;
    cursor: pointer;
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -10px;
    background-color: var(--accent-color);
    color: var(--bg-color);
    font-size: 0.7rem;
    font-weight: bold;
    height: 18px;
    width: 18px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Hero */
.hero {
    height: 100vh;
    background: linear-gradient(rgba(0,0,0,0.5), rgba(0,0,0,0.7)), url('https://images.unsplash.com/photo-1469334031218-e382a71b716b?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80') center/cover;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding-top: 60px; /* Offset for fixed header */
}

.hero-content {
    max-width: 800px;
    padding: 2rem;
}

.hero-content span {
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 3px;
    color: var(--accent-color);
    margin-bottom: 1rem;
    display: inline-block;
}

.hero-content h1 {
    font-family: var(--font-heading);
    font-size: 5rem;
    line-height: 1.1;
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.hero-content p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin-bottom: 2.5rem;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 1rem 2.5rem;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 600;
    cursor: pointer;
    border: none;
    transition: all 0.3s ease;
}

.btn-primary {
    background-color: var(--accent-color);
    color: var(--bg-color);
}

.btn-primary:hover {
    background-color: var(--accent-hover);
    transform: translateY(-2px);
}

.btn-outline {
    background-color: transparent;
    border: 1px solid var(--accent-color);
    color: var(--accent-color);
}

.btn-outline:hover {
    background-color: var(--accent-color);
    color: var(--bg-color);
}

/* Featured Products */
.featured-products {
    padding: 6rem 0;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    transition: transform 0.3s ease;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    transform: translateY(-5px);
    border-color: #555;
}

.product-image {
    position: relative;
    overflow: hidden;
    aspect-ratio: 3/4;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-badge {
    position: absolute;
    top: 1rem;
    left: 1rem;
    background-color: var(--accent-color);
    color: var(--bg-color);
    padding: 0.25rem 0.75rem;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    z-index: 1;
}

.product-info {
    padding: 1.5rem;
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.product-category {
    font-size: 0.8rem;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 0.5rem;
}

.product-title {
    font-family: var(--font-heading);
    font-size: 1.25rem;
    margin-bottom: 1rem;
}

.product-price {
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--accent-color);
    margin-bottom: 1.5rem;
    margin-top: auto;
}

.add-to-cart {
    width: 100%;
    padding: 0.75rem;
    background-color: var(--surface-color-light);
    color: var(--text-primary);
    border: 1px solid var(--border-color);
    cursor: pointer;
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 1px;
    transition: all 0.3s ease;
}

.add-to-cart:hover {
    background-color: var(--text-primary);
    color: var(--bg-color);
}

/* Deals Section */
.deals {
    padding: 6rem 0;
    background-color: var(--surface-color);
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
}

.deals-container {
    display: flex;
    align-items: center;
    gap: 4rem;
}

.deal-content {
    flex: 1;
}

.deal-content h2 {
    font-family: var(--font-heading);
    font-size: 3rem;
    margin-bottom: 1rem;
    line-height: 1.2;
}

.deal-content p {
    font-size: 1.1rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.countdown {
    display: flex;
    gap: 1.5rem;
    margin-bottom: 2.5rem;
}

.time-box {
    background-color: var(--bg-color);
    border: 1px solid var(--border-color);
    padding: 1rem;
    min-width: 80px;
    text-align: center;
}

.time-box span {
    display: block;
    font-family: var(--font-heading);
    font-size: 2rem;
    color: var(--accent-color);
}

.time-box small {
    display: block;
    font-size: 0.8rem;
    text-transform: uppercase;
    color: var(--text-secondary);
    margin-top: 0.5rem;
}

.deal-image {
    flex: 1;
    position: relative;
}

.deal-image img {
    border-radius: 4px;
    box-shadow: 0 20px 40px rgba(0,0,0,0.5);
}

/* Editorial */
.editorial {
    padding: 6rem 0;
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 3rem;
}

.editorial-card {
    background-color: var(--surface-color);
    overflow: hidden;
    border: 1px solid var(--border-color);
    transition: transform 0.3s ease;
}

.editorial-card:hover {
    transform: translateY(-5px);
}

.editorial-card img {
    width: 100%;
    height: 300px;
    object-fit: cover;
}

.editorial-content {
    padding: 2rem;
}

.editorial-content .category {
    font-size: 0.8rem;
    color: var(--accent-color);
    text-transform: uppercase;
    letter-spacing: 2px;
    margin-bottom: 1rem;
    display: inline-block;
}

.editorial-content h3 {
    font-family: var(--font-heading);
    font-size: 1.75rem;
    margin-bottom: 1rem;
    line-height: 1.3;
}

.editorial-content p {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
}

.read-more {
    font-weight: 600;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
}

.read-more:hover {
    color: var(--accent-color);
}

/* Footer */
footer {
    background-color: #050505;
    padding-top: 5rem;
    border-top: 1px solid var(--border-color);
}

.footer-container {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: 3rem;
    margin-bottom: 3rem;
