    border-top: 1px solid var(--border-color);
    color: var(--text-secondary);
    font-size: 0.9rem;
}

.social-icons {
    display: flex;
    gap: 1.5rem;
}

.social-icons a {
    color: var(--text-secondary);
    font-size: 1.2rem;
}

.social-icons a:hover {
    color: var(--text-primary);
}

/* Responsive */
@media (max-width: 992px) {
