// Product Data
const products = [
    {
        id: 1,
        title: "Velvet Midnight Blazer",
        category: "Outerwear",
        price: 345.00,
        image: "https://images.unsplash.com/photo-1591047139829-d91aecb6caea?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80",
        badge: "New"
    },
    {
        id: 2,
        title: "Silk Essential Blouse",
        category: "Tops",
        price: 185.00,
        image: "https://images.unsplash.com/photo-1621072156002-e2fcc60bfd91?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80",
        badge: null
    },
    {
        id: 3,
        title: "Structured Wide-Leg Trouser",
        category: "Bottoms",
        price: 220.00,
        image: "https://images.unsplash.com/photo-1594633312681-425c7b97ccd1?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80",
        badge: "Bestseller"
    },
    {
        id: 4,
        title: "Leather Crossbody Bag",
        category: "Accessories",
        price: 295.00,
        image: "https://images.unsplash.com/photo-1590874103328-eac38a683ce7?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80",
        badge: null
    }
];

// Render Products
const productGrid = document.getElementById('product-grid');

function renderProducts() {
    products.forEach(product => {
        const badgeHTML = product.badge ? `<span class="product-badge">${product.badge}</span>` : '';

        const productCard = document.createElement('div');
        productCard.className = 'product-card';
        productCard.innerHTML = `
            <div class="product-image">
                ${badgeHTML}
                <img src="${product.image}" alt="${product.title}">
            </div>
            <div class="product-info">
                <span class="product-category">${product.category}</span>
                <h3 class="product-title">${product.title}</h3>
                <span class="product-price">$${product.price.toFixed(2)}</span>
                <button class="add-to-cart" data-id="${product.id}">Add to Cart</button>
            </div>
        `;
        productGrid.appendChild(productCard);
    });
}

// Cart Functionality
let cartCount = 0;
const cartCountElement = document.querySelector('.cart-count');

function initCart() {
    const addToCartButtons = document.querySelectorAll('.add-to-cart');

    addToCartButtons.forEach(button => {
        button.addEventListener('click', (e) => {
            cartCount++;
            cartCountElement.textContent = cartCount;

            // Visual feedback
            const originalText = e.target.textContent;
            e.target.textContent = 'Added!';
            e.target.style.backgroundColor = 'var(--text-primary)';
            e.target.style.color = 'var(--bg-color)';

            setTimeout(() => {
                e.target.textContent = originalText;
                e.target.style.backgroundColor = '';
                e.target.style.color = '';
            }, 1000);
        });
    });
}

// Countdown Timer
function initCountdown() {
    // Set date to 2 days from now for demo purposes
    const endDate = new Date();
    endDate.setDate(endDate.getDate() + 2);
    endDate.setHours(endDate.getHours() + 14);
    endDate.setMinutes(endDate.getMinutes() + 35);

    const daysEl = document.getElementById('days');
    const hoursEl = document.getElementById('hours');
    const minsEl = document.getElementById('mins');
    const secsEl = document.getElementById('secs');

    function updateTimer() {
        const now = new Date();
        const difference = endDate - now;

        if (difference <= 0) {
            clearInterval(timerInterval);
            return;
        }

        const days = Math.floor(difference / (1000 * 60 * 60 * 24));
        const hours = Math.floor((difference % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
        const minutes = Math.floor((difference % (1000 * 60 * 60)) / (1000 * 60));
        const seconds = Math.floor((difference % (1000 * 60)) / 1000);

        if (daysEl) daysEl.textContent = days.toString().padStart(2, '0');
        if (hoursEl) hoursEl.textContent = hours.toString().padStart(2, '0');
        if (minsEl) minsEl.textContent = minutes.toString().padStart(2, '0');
        if (secsEl) secsEl.textContent = seconds.toString().padStart(2, '0');
    }

    updateTimer();
    const timerInterval = setInterval(updateTimer, 1000);
}

// Newsletter Form
document.getElementById('newsletter-form').addEventListener('submit', (e) => {
    e.preventDefault();
    const input = e.target.querySelector('input');
    const button = e.target.querySelector('button');

    if(input.value) {
        button.textContent = 'Subscribed!';
        button.style.backgroundColor = 'var(--accent-color)';
        input.value = '';

        setTimeout(() => {
            button.textContent = 'Subscribe';
            button.style.backgroundColor = '';
        }, 3000);
    }
});

// Initialize
document.addEventListener('DOMContentLoaded', () => {
    renderProducts();
    initCart();
    initCountdown();
